    if(typeof v==='object')return `<dl class="cell-fields">${Object.entries(v).filter(([k])=>!/telefone|phone|jid|cpf|senha|password|token|secret/i.test(k)).map(([k,x])=>`<div><dt>${esc(fieldLabel(k))}</dt><dd>${cellValue(x)}</dd></div>`).join('')}</dl>`;
