      return `${y?`<div class="notice">Canal oficial: as transmissões da aba Ao vivo são a principal fonte e aparecem primeiro; a lista também inclui vídeos comuns do canal. ${youtubeStatus}${window} São analisadas as legendas públicas em português e, quando autorizadas, as faixas acessíveis pela conta do canal. Quando a legenda não é recuperada, o conteúdo não é inferido. ${data.youtube_curadoria?'':'A curadoria desta coleta está pendente; eventual síntese anterior permanece identificada no histórico diário.'}${y.limitations?` ${esc(y.limitations)}`:''}</div>${data.youtube_curadoria?`<div class="subsection"><h3>Curadoria dos vídeos recentes</h3>${renderData(data.youtube_curadoria,'youtube')}</div>`:''}${data.youtube_curadoria_historica?`<details class="conversation-history"><summary>Ver síntese anterior do YouTube</summary>${renderData(data.youtube_curadoria_historica,'youtube')}</details>`:''}${dataTable(y.videos,[['source_tab','Origem'],['published_display','Publicado'],['titulo','Vídeo','wide'],['caption_status','Análise da legenda'],['caption_language','Idioma'],['descricao','Descrição','wide'],['url','Assistir']],'Canal oficial · Ao vivo primeiro, demais vídeos depois')}`:''}${renderData(data.pregacoes,key)}${data.videos?`<h3>Vídeos recentes</h3>${dataTable(data.videos,[['data','Data','date'],['titulo','Vídeo','wide'],['url','Assistir']],'Vídeos recentes')}`:''}${data.acervo_sermoes?`<h3>Acervo</h3>${renderData(data.acervo_sermoes,key)}`:''}`;
